<style>
:root{--ia-accent:<?=h($accent)?>;--ia-bg:#f5f7fa;--ia-border:#e5e7eb;--ia-surface:#fff;--ia-text:#172033;--ia-muted:#667085;--ia-danger:#d92d20}*{box-sizing:border-box}body{margin:0;background:var(--ia-bg);color:var(--ia-text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}.portal-top{height:64px;background:#fff;border-bottom:1px solid var(--ia-border);display:flex;align-items:center;justify-content:space-between;padding:0 24px;box-shadow:0 1px 3px rgba(16,24,40,.06)}.brand{display:flex;align-items:center;gap:12px}.brand img{max-width:180px;max-height:42px;object-fit:contain}.brand-text strong{display:block;color:#111827;font-size:15px}.brand-text span{display:block;color:#667085;font-size:10px}.portal-user{font-size:13px;color:#475467}.portal-user a{color:var(--ia-accent);font-weight:600;text-decoration:none;margin-left:10px}.wrap{max-width:1180px;margin:0 auto;padding:24px}.page-head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:14px}.page-head h1{margin:0;color:#101828;font-size:26px}.page-head p{margin:4px 0 0;color:var(--ia-muted)}.tabs{display:flex;gap:6px;margin-bottom:18px}.tabs a{padding:9px 13px;border-radius:6px;text-decoration:none;color:#475467;font-weight:600}.tabs a.active{background:var(--ia-accent);color:#fff}.card{background:#fff;border:1px solid var(--ia-border);border-radius:8px;padding:20px;margin-bottom:18px;box-shadow:0 1px 2px rgba(16,24,40,.04)}.card h2{margin:0 0 14px;color:#101828;font-size:19px}.login-brand{text-align:center;margin-bottom:20px}.login-brand img{max-width:min(440px,80vw);max-height:100px;object-fit:contain}.login-card{max-width:430px;margin:70px auto;padding:26px}.login-card h2{text-align:center;font-size:22px}.login-card .sub{text-align:center;color:var(--ia-muted);margin:-6px 0 18px}label{display:block;color:#344054;font-weight:600;margin:10px 0 5px}input,select,textarea{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:6px;background:#fff;color:#101828}input[type=checkbox]{width:auto;margin-right:7px}.check{display:flex;align-items:center;font-weight:500;margin:9px 0}.btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--ia-accent);border-radius:6px;padding:9px 13px;background:var(--ia-accent);color:#fff!important;font-weight:600;text-decoration:none;cursor:pointer}.btn.red{background:var(--ia-danger);border-color:var(--ia-danger)}.btn.gray{background:#fff;border-color:#d0d5dd;color:#344054!important}.grid{display:grid;grid-template-columns:1fr 1.25fr;gap:18px}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.alert{padding:11px 13px;border-radius:7px;margin-bottom:14px;border:1px solid}.bad{background:#fef3f2;border-color:#fecdca;color:#b42318}.good{background:#ecfdf3;border-color:#abefc6;color:#067647}.tablewrap{overflow:auto;border:1px solid var(--ia-border);border-radius:7px}table{width:100%;border-collapse:collapse;min-width:850px;background:#fff}th,td{padding:10px;border-bottom:1px solid #e4e7ec;text-align:left;font-size:13px}th{background:#f2f4f7;color:#344054;font-size:11px;font-weight:700}tr:last-child td{border-bottom:0}.status{font-weight:700}.small{font-size:12px;color:var(--ia-muted)}.actions,.form-actions{display:flex;gap:8px;flex-wrap:wrap}.form-actions{margin-top:14px}.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 14px}.profile-grid .wide{grid-column:1/-1}.portal-footer{text-align:center;color:#98a2b3;font-size:11px;padding:18px 10px 30px}.portal-footer strong{color:#667085}@media(max-width:760px){.grid,.settings-grid,.profile-grid{grid-template-columns:1fr}.profile-grid .wide{grid-column:auto}.wrap{padding:12px}.portal-top{padding:0 12px;height:58px}.brand img{max-width:150px;max-height:36px}.brand-text{display:none}.page-head{display:block}.login-card{margin:35px auto}.portal-user{font-size:12px}.tabs{overflow:auto}}

body.theme-refined{--ia-bg:#eef3f8;background:linear-gradient(180deg,#edf3f8 0,#f7f9fc 300px,#f5f7fa 100%)}
body.theme-refined .portal-top{height:72px;background:linear-gradient(115deg,#101828 0,#1f2937 72%,var(--ia-accent) 145%);border-bottom:3px solid var(--ia-accent);box-shadow:0 8px 26px rgba(16,24,40,.16)}
body.theme-refined .brand{min-height:50px}body.theme-refined .brand img{background:#fff;border-radius:10px;padding:6px 10px;max-width:205px;max-height:50px;box-shadow:0 3px 12px rgba(0,0,0,.16)}body.theme-refined .brand-text strong,body.theme-refined .brand-text span,body.theme-refined .portal-user{color:#fff}body.theme-refined .brand-text span{opacity:.72}body.theme-refined .portal-user a{color:#fff;background:rgba(255,255,255,.12);padding:7px 10px;border-radius:7px}body.theme-refined .portal-user a:hover{background:rgba(255,255,255,.2)}
body.theme-refined .wrap{padding-top:28px}body.theme-refined .page-head{background:linear-gradient(135deg,#fff 0,#fff 70%,color-mix(in srgb,var(--ia-accent) 8%,white) 100%);border:1px solid #dfe7ef;border-left:5px solid var(--ia-accent);border-radius:12px;padding:18px 20px;margin-bottom:16px;box-shadow:0 5px 18px rgba(16,24,40,.06)}body.theme-refined .page-head h1{font-size:28px;letter-spacing:-.35px}
body.theme-refined .tabs{background:#fff;border:1px solid #dfe7ef;border-radius:10px;padding:5px;display:inline-flex;box-shadow:0 3px 12px rgba(16,24,40,.05)}body.theme-refined .tabs a{border-radius:7px;padding:9px 16px}body.theme-refined .tabs a:not(.active):hover{background:#f1f5f9;color:var(--ia-accent)}
body.theme-refined .card{border-color:#dfe7ef;border-radius:12px;box-shadow:0 5px 18px rgba(16,24,40,.055);position:relative;overflow:hidden}body.theme-refined .card:before{content:"";position:absolute;left:0;top:0;width:100%;height:3px;background:linear-gradient(90deg,var(--ia-accent),transparent 70%);opacity:.85}body.theme-refined .card h2{letter-spacing:-.2px}body.theme-refined input,body.theme-refined select,body.theme-refined textarea{border-radius:8px;border-color:#cfd8e3;padding:11px}body.theme-refined input:focus,body.theme-refined select:focus,body.theme-refined textarea:focus{outline:0;border-color:var(--ia-accent);box-shadow:0 0 0 3px color-mix(in srgb,var(--ia-accent) 15%,transparent)}body.theme-refined .btn{border-radius:8px;padding:9px 15px;box-shadow:0 2px 5px rgba(16,24,40,.08);transition:.15s ease}body.theme-refined .btn:hover{transform:translateY(-1px);filter:brightness(.97)}body.theme-refined .btn.gray{box-shadow:none}
body.theme-refined .tablewrap{border-color:#dfe7ef;border-radius:10px;box-shadow:inset 0 1px 0 rgba(255,255,255,.7)}body.theme-refined th{background:#edf3f8;color:#344054;padding:11px}body.theme-refined td{padding:11px}body.theme-refined tbody tr:hover td{background:#f8fbfd}body.theme-refined .login-card{margin-top:58px;border:0;border-top:4px solid var(--ia-accent);box-shadow:0 18px 45px rgba(16,24,40,.15);padding:32px}body.theme-refined .login-brand img{max-height:112px}body.theme-refined .portal-footer{padding-top:24px}
@media(max-width:760px){body.theme-refined .portal-top{height:64px}body.theme-refined .brand img{max-width:160px;max-height:42px;padding:5px 8px}body.theme-refined .page-head{padding:14px 15px}body.theme-refined .tabs{display:flex;width:100%}body.theme-refined .tabs a{flex:1;text-align:center}}
</style>
